// Matches ANSI color / escape sequences (e.g. \x1B[0m).
// eslint-disable-next-line no-control-regex
const ANSI_COLOR_REGEX = /\x1B\[[0-9;]*[A-Za-z]/g;
// Matches remaining control characters.
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS_REGEX = /[\x00-\x1F\x7F]/g;

const READ_LOGS_TIMEOUT_IN_MS = 30 * 1000;

/**
 * @description Read Zigbee2mqtt container logs and detect fatal errors.
 * @param {string} containerId - Docker container id.
 * @returns {Promise} Resolve when the logs have been analyzed.
 * @example
 * await this.readZ2mContainerLogs('container-id');
 */
async function readZ2mContainerLogs(containerId) {
  let knownErrorDetected = false;
  let lastGenericErrorLine = null;
  let streamFailed = false;

  try {
    const logStream = await this.gladys.system.getContainerLogs(containerId, { follow: true });

    await new Promise((resolve) => {
      let finished = false;
      let timeout = null;

      const finish = () => {
        if (finished) {
          return;
        }
        finished = true;
        if (timeout) {
          clearTimeout(timeout);
        }
        if (logStream && typeof logStream.destroy === 'function') {
          logStream.destroy();
        }
        resolve();
      };

      timeout = setTimeout(finish, READ_LOGS_TIMEOUT_IN_MS);

      logStream.on('data', (chunk) => {
        const lines = chunk.toString().split('\n');
        lines.forEach((rawLine) => {
          if (!rawLine) {
            return;
          }
          // Strip the Docker stream prefix byte (first character)
          let line = rawLine.slice(1);
          // Strip ANSI color codes
          line = line.replace(ANSI_COLOR_REGEX, '');
          // Strip remaining control characters
          line = line.replace(CONTROL_CHARS_REGEX, '');

          // Known error: EZSP protocol version not supported by Host
          if (line.includes('Adapter EZSP protocol version') && line.includes('is not supported by Host')) {
            knownErrorDetected = true;
            finish();
            return;
          }

          // Generic error detection
          if (/error:/i.test(line)) {
            lastGenericErrorLine = line.trim();
          }
        });
      });

      logStream.on('end', finish);
      logStream.on('error', (e) => {
        logger.debug('Error while reading Zigbee2mqtt container logs:', e);
        streamFailed = true;
        finish();
      });
    });
  } catch (e) {
    logger.debug('Unable to read Zigbee2mqtt container logs:', e);
    streamFailed = true;
  }

  if (streamFailed) {
    this.z2mContainerError = null;
  } else if (knownErrorDetected) {
    // Known error code takes precedence over any generic error lines
    this.z2mContainerError = { code: 'EZSP_PROTOCOL_VERSION', message: null };
  } else if (lastGenericErrorLine !== null) {
    this.z2mContainerError = { code: null, message: lastGenericErrorLine };
  } else {
    this.z2mContainerError = null;
  }

  this.emitStatusEvent();
}

module.exports = {
  readZ2mContainerLogs,
};
